const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const regionCenter = ee.Geometry.Point([-8.17, 39.92]); // Pedrógão Grande vicinity
  const region = regionCenter.buffer(15000); // 15 km buffer
  const windowStart = '2017-06-16';
  const windowEndExcl = '2017-06-21'; // exclusive end
  const monthStart = '2017-06-01';
  const monthEndExcl = '2017-07-01';
  const doyStart = 167; // 2017-06-16
  const doyEnd = 171;   // 2017-06-20

  // 2. Data Acquisition & Check with fallback
  const candidateIds = ['MODIS/006/MCD64A1', 'MODIS/061/MCD64A1'];
  let chosenId = null;
  let col = null;
  for (let i = 0; i < candidateIds.length; i++) {
    try {
      const tryId = candidateIds[i];
      const tryCol = ee.ImageCollection(tryId).filterDate(monthStart, monthEndExcl);
      const size = await tryCol.size().getInfo();
      console.log(`Dataset check: ${tryId} -> ${size} images (June 2017)`);
      if (size > 0) {
        chosenId = tryId;
        col = tryCol;
        break;
      }
    } catch (e) {
      console.log(`Error loading ${candidateIds[i]}: ${e.message || e}`);
    }
  }
  if (!chosenId && !col) {
    console.log('No usable burned-area dataset loaded.');
    console.log('C1');
    return;
  }

  // 3. Processing
  const img = col.mosaic(); // monthly mosaic
  const burnDate = img.select('BurnDate'); // 0 = unburned, 1..366 = DOY
  const burnedWindowMask = burnDate.gte(doyStart).and(burnDate.lte(doyEnd)).rename('bw').int();

  // Compute valid pixel count (any pixel present in BurnDate band)
  let validCount = null;
  let burnedCount = null;
  try {
    const validDict = await burnDate.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: 1000,
      maxPixels: 1e9
    }).getInfo();
    const burnedDict = await burnedWindowMask.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: region,
      scale: 1000,
      maxPixels: 1e9
    }).getInfo();
    validCount = validDict ? validDict['BurnDate'] : null;
    burnedCount = burnedDict ? burnedDict['bw'] : null;
  } catch (e) {
    console.log(`reduceRegion failure: ${e.message || e}`);
    console.log('D');
    return;
  }

  // 4. Validation & Final Answer Logic
  if (validCount === null || typeof validCount === 'undefined') {
    console.log('Valid pixel count is null/undefined.');
    console.log('C3');
    return;
  }
  if (validCount === 0) {
    console.log('No valid pixels in region after processing.');
    console.log('C2');
    return;
  }
  if (burnedCount === null || typeof burnedCount === 'undefined') {
    console.log('Burned pixel sum is null/undefined.');
    console.log('C3');
    return;
  }
  const burnedPct = (burnedCount / validCount) * 100.0;

  // 5. Evidence Output (concise, <= 20 lines)
  console.log('Region: Pedrógão Grande (15 km buffer)');
  console.log(`Time window: ${windowStart} to ${windowEndExcl} (DOY ${doyStart}-${doyEnd}, 2017)`);
  console.log(`Dataset used: ${chosenId}`);
  console.log(`Valid pixels: ${validCount}`);
  console.log(`Burned pixels (DOY ${doyStart}-${doyEnd}): ${burnedCount}`);
  console.log(`Burned % of valid: ${burnedPct.toFixed(3)}%`);

  // 6. Final Answer
  if (!isFinite(burnedPct) || burnedPct < 0) {
    console.log('C3');
  } else if (burnedCount > 0) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
